pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Normalized progress in the stream
    let progress = step_index as f64 / total_items as f64;
    // Residuals normalized to [0,1]
    let post_norm = post_residual as f64 / bin_capacity as f64;
    let mean_norm = mean_residual / bin_capacity as f64;

    // Base score: remaining space (larger residual -> higher score)
    let mut score = post_residual as f64;

    // Penalize bins that leave a lot of unused space (non‑linear)
    score += 200.0 * (1.0 - post_norm).powi(2);

    // Smooth penalty that encourages early placement of items
    score += 1000.0 * (progress - 0.5).powi(3);

    // Reward bins whose residual is close to the current mean residual
    score -= 50.0 * (mean_norm - post_norm);

    // Penalize if the next item would not fit in the remaining space
    let next_diff = next_item_size as i32 - post_residual as i32;
    if next_diff > 0 {
        score += 100.0 * next_diff as f64;
    }

    // Favor the last fitting bin to avoid opening a new one
    if fitting_bins_count == 1 {
        score -= 500.0;
    }

    // Small penalty for having many open bins (encourage consolidation)
    score += 10.0 * open_bins_count as f64;

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let mut score = post_residual as f64;
    let step_frac = (step_index as f64) / (total_items as f64);

    // 1. If this is the only bin that can fit, heavily reward it
    if fitting_bins_count == 1 {
        score -= 5000.0;
    } else {
        // Penalize when many bins can fit (choosing a sub‑optimal one)
        score += (fitting_bins_count as f64) * 5.0;
    }

    // 2. Lookahead: prefer residual close to the next item size
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score -= 1000.0 / (1.0 + diff);
    }

    // 3. Penalize deviation from the mean residual across open bins
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score += mean_diff * 5.0;

    // 4. Prefer using an existing bin when many are open
    score -= (open_bins_count as f64) * 1.0;

    // 5. New‑bin candidate logic
    if bin_residual == bin_capacity {
        if open_bins_count > 5 && step_frac > 0.7 {
            // Late in stream with many bins: discourage opening a new one
            score += 500.0;
        } else {
            // Early or few open bins: encourage new bin
            score -= 200.0;
        }
    }

    // 6. Small adjustment based on stream progress
    score += step_frac * 10.0;

    score
}

