pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: remaining space after placement
    let mut score = post_residual as f64;

    // Strict dead‑space avoidance: heavily penalise tiny gaps
    if post_residual <= 5 {
        score += 200.0;
    } else if post_residual <= 10 {
        score += 50.0;
    } else if post_residual <= 20 {
        score += 10.0;
    }

    // Pressure from open bins – use existing bins whenever possible
    score -= (open_bins_count as f64) * 5.0;

    // Slight adjustment based on the mean residual of all open bins
    // (encourage bins that bring the average down a little)
    score += (mean_residual - post_residual as f64) * 0.1;

    // If the next item is larger than the space left, penalise this bin
    if next_item_size > 0 && post_residual < next_item_size {
        score += 100.0;
    }

    // If this is the only bin that can fit the item, give it a small bonus
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(
    _item_size: u32,
    bin_residual: u32,
