    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: the smaller the leftover space, the better
    let mut score = post_residual as f64;

    // 1. Strict dead space avoidance:
    //   Penalize very small gaps that are likely to be wasted.
    if post_residual < 5 {
        score += 10.0 * (5 - post_residual) as f64;
    }

    // 2. Look‑ahead penalty:
    //   If the next item cannot fit into the remaining space,
    //   this bin will become unusable for it, so penalize.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 5.0 * (next_item_size - post_residual) as f64;
    }

    // 3. Open‑bins pressure:
    //   Prefer using existing bins over opening a new one.
    if bin_residual == bin_capacity {
        // Candidate is a brand‑new bin
        if open_bins_count > 0 {
            score += 20.0 * open_bins_count as f64;
        }
    } else {
        // Existing bin: reward the unique fitting bin
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // 4. Late‑stream tightening:
    //   Near the end of the stream, dead space becomes more costly.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual < 10 {
        score += 5.0 * (10 - post_residual) as f64;
    }

    // 5. Residual balance:
    //   Penalize bins whose residual is far below the current mean.
    if mean_residual > 0.0 && (post_residual as f64) < mean_residual {
        score += (mean_residual - post_residual as f64) * 0.5;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Normalized stream progress
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Polynomial coupling of post_residual with stream progress
    let progress_factor = 1.0 + 3.0 * progress - 2.0 * progress * progress;
    let mut score = post * progress_factor;

    // Penalize opening a new bin when many bins are already open
    if bin_residual == bin_capacity {
        let open_factor = open_bins_count as f64 / (open_bins_count as f64 + 1.0);
        score += 10.0 * open_factor;
    }

    // Lookahead penalty: if next item won't fit in the residual after this placement
    if next_item_size > 0 {
        let diff = next_item_size as f64 - post;
        if diff > 0.0 {
            score += diff * diff; // quadratic penalty
        }
    }

    // Reward bins that are the last chance before opening a new one
    if fitting_bins_count == 1 {
        score *= 0.7;
    }

    // Slight penalty for high mean residual across all open bins
    score += mean_residual * 0.05;

    // Reward exact or close fits
    let closeness = (bin_residual as f64 - item_size as f64).abs();
    score -= 5.0 / (1.0 + closeness);

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Normalised stream progress
    let progress = step_index as f64 / total_items as f64;

    // Base score is the post‑residual
    let mut score = post_residual as f64;

    // 1. Prefer tighter fits as we approach the end of the stream
    let residual_sq = (post_residual as f64).powi(2);
    let progress_sq = progress * progress;
    let next_factor = 1.0 - (next_item_size as f64 / bin_capacity as f64);
    score -= residual_sq * progress_sq * next_factor;

    // 2. Penalise opening a new bin when many bins are already open
    if bin_residual == bin_capacity {
        let open_factor = open_bins_count as f64 / (total_items as f64 + 1.0);
        score -= open_factor * (post_residual as f64) * (1.0 - progress);
    }

    // 3. Slightly favour bins whose residual is close to the mean residual
    let mean_diff = (mean_residual - post_residual as f64).abs();
    score -= mean_diff * (1.0 - progress);

    // 4. If this is the last chance to place the item, give a small bonus
    if fitting_bins_count == 1 {
        score -= (post_residual as f64) * 0.1 * (1.0 - progress);
    }

    score
}
